import re
import six


class EmssAttribute(object):
    def __init__(self, attribute, value):
        self.attribute = attribute
        self.value = value
        self.emss_format = ""
        self._parse_value()
        self._parse_attribute()

    def get_emss_format(self):
        return self.emss_format

    def get_list(self):
        return [self.attribute, self.value]

    def _is_structural_attribute(self):
        return re.match(r'^\w+\.\w+', self.attribute)

    def _has_index(self):
        return bool(re.match(r'\S+\[(\d|,)+\]$', self.attribute))

    def _parse_value(self):
        if not isinstance(self.value, six.string_types):
            return
        if re.match(r'\S+\s+\S+', self.value) and not re.match('"', self.value):
            self.value = '"' + self.value + '"'

    def _parse_structural_attribute(self):
        if not self._has_index():
            self.attribute = "%s[0]" % self.attribute
        return "%s [%s]" % (self.attribute, self.value)

    def _parse_normal_attribute(self):
        return "%s %s" % (self.attribute, self.value)

    def _parse_attribute(self):
        if self._is_structural_attribute():
            self.emss_format = self._parse_structural_attribute()
        else:
            self.emss_format = self._parse_normal_attribute()


def transform_dict_of_attributes_to_emss_input_list(dict_of_attributes):
    return [EmssAttribute(a, v).get_emss_format() for a, v in dict_of_attributes.items()]


def transform_dict_of_attributes_to_list(dict_of_attributes):
    ret_list = []
    for a, v in dict_of_attributes.items():
        attr = EmssAttribute(a, v)
        ret_list.extend(attr.get_list())
    return ret_list
